package com.treepeople.leapmindtts.service.profile.platform;
import java.math.BigDecimal; import java.time.Instant; import java.util.List;
public record LecturingProfileContext(Long userId, String sceneType, ProfileContextStatus profileStatus, String statusReason, Long profileVersion, Instant computedAt, Instant lastUpdated, BigDecimal confidence, ProfileAvailability availability, List<ProfileKnowledgeContext> weakKnowledgePoints, List<ProfileRecentFocus> recentFocus, String learningPace, List<String> preferredContentModes, String summaryText) {
    public LecturingProfileContext { boolean facts = !ProfileContextFields.list(weakKnowledgePoints).isEmpty() || !ProfileContextFields.list(recentFocus).isEmpty() || learningPace != null || !ProfileContextFields.list(preferredContentModes).isEmpty() || summaryText != null; ProfileContextFields.envelope(userId, sceneType, "lecturing", profileStatus, statusReason, profileVersion, computedAt, lastUpdated, confidence, availability, facts); weakKnowledgePoints = ProfileContextFields.list(weakKnowledgePoints, 5, "weakKnowledgePoints"); recentFocus = ProfileContextFields.list(recentFocus, 3, "recentFocus"); learningPace = ProfileContextFields.pace(learningPace); preferredContentModes = ProfileContextFields.contentModes(preferredContentModes); summaryText = ProfileContextFields.summary(summaryText); }
}
